interface RateLimitConfig {
    maxRequests: number;
    windowMs: number;
}

interface RateLimitEntry {
    count: number;
    resetTime: number;
}

const DEFAULT_CONFIG: RateLimitConfig = {
    maxRequests: 100,
    windowMs: 60000,
};

export class RateLimiter {
    private cache: Map<string, RateLimitEntry> = new Map();
    private config: RateLimitConfig;

    public constructor(config: Partial<RateLimitConfig> = {}) {
        this.config = { ...DEFAULT_CONFIG, ...config };
    }

    public checkLimit(key: string): { allowed: boolean; remaining: number; resetAt: number } {
        const now = Date.now();
        let entry = this.cache.get(key);

        if (!entry || now > entry.resetTime) {
            entry = {
                count: 0,
                resetTime: now + this.config.windowMs,
            };
            this.cache.set(key, entry);
        }

        entry.count++;
        const remaining = Math.max(0, this.config.maxRequests - entry.count);
        const resetAt = entry.resetTime;

        if (entry.count > this.config.maxRequests) {
            return { allowed: false, remaining: 0, resetAt };
        }

        return { allowed: true, remaining, resetAt };
    }

    public getResetTime(key: string): number {
        const entry = this.cache.get(key);
        return entry?.resetTime || Date.now() + this.config.windowMs;
    }

    public reset(key: string): void {
        this.cache.delete(key);
    }

    public clear(): void {
        this.cache.clear();
    }
}

export function createRateLimiter(config?: Partial<RateLimitConfig>): RateLimiter {
    return new RateLimiter(config);
}

export const GLOBAL_RATE_LIMITER = createRateLimiter();
